import json, re, random, time, chess, os

D = os.path.dirname(os.path.abspath(__file__))
RX = [(re.compile(p), r) for p, r in json.load(open(os.path.join(D, "re.json")))]


def run(fen):
    for p, r in RX:
        fen = p.sub(r, fen)
    return fen.split("\n")


def expected(fen):
    b = chess.Board(fen)
    out = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        c = b.copy(); c.push(m)
        out.add(" ".join(c.fen().split(" ")[:-2]))
    return out


def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    exp = expected(fen)
    if not exp and ours == [""]:
        return True
    ok = len(ours) == len(exp) and all(
        x in exp or x.rpartition(" ")[0] + " -" in exp for x in ours)
    if not ok:
        print("FAIL", fen)
        print(" extra:", [x for x in ours if not (x in exp or x.rpartition(" ")[0] + " -" in exp)])
        print(" missing:", exp - set(ours) - {x.rpartition(" ")[0] + " -" for x in ours})
    return ok


ex = "<REDACTED_B64> w kq - 0 1"
print(run(ex))
random.seed(int(os.environ.get("SEED", "1")))
n = 0; bad = 0; t0 = time.time()
for g in range(int(os.environ.get("GAMES", "200"))):
    b = chess.Board()
    for ply in range(random.randint(1, 200)):
        if b.is_game_over():
            break
        if b.turn == chess.WHITE:
            n += 1
            if not check(b.fen()):
                bad += 1
                if bad > 5:
                    raise SystemExit
        moves = list(b.legal_moves)
        # bias toward captures/castling/ep for coverage
        sp = [m for m in moves if b.is_castling(m) or b.is_en_passant(m) or m.promotion]
        b.push(random.choice(sp) if sp and random.random() < 0.7 else random.choice(moves))
print("positions", n, "bad", bad, "time/pos", (time.time() - t0) / max(n, 1))
